'use strict';
const $ = selector => document.querySelector(selector);
const states = ['Waiting', 'In progress', 'Ready'];
const ticket = id => '#' + String(id).padStart(3, '0');
let db, rows = [], filter = 'All', saving = false;

function element(name, className, value) {
  const node = document.createElement(name);
  if (className) node.className = className;
  if (value !== undefined) node.textContent = value;
  return node;
}
function report(message) {
  $('#error').hidden = !message;
  $('#error').textContent = message;
}
function message(value) { $('#notice').textContent = value; }

$('#date').textContent = new Intl.DateTimeFormat(undefined, {weekday:'long', month:'long', day:'numeric', year:'numeric'}).format(new Date());
function renumber() {
  const fields = [...$('#fields').children];
  fields.forEach((field, i) => {
    field.querySelector('legend').textContent = 'Item ' + (i + 1);
    field.querySelector('.remove').hidden = fields.length === 1;
  });
  $('#more').disabled = fields.length >= 3;
}
function addItem(focus = true) {
  if ($('#fields').children.length >= 3) return;
  const field = $('#item').content.firstElementChild.cloneNode(true);
  const detail = field.querySelector('.detail');
  field.querySelector('.request').onchange = event => {
    detail.hidden = event.target.value !== 'Other repair';
    detail.firstElementChild.required = !detail.hidden;
    if (!detail.hidden) detail.firstElementChild.focus();
  };
  field.querySelector('.remove').onclick = () => {
    field.remove();
    renumber();
    $('#more').focus();
  };
  $('#fields').append(field);
  renumber();
  if (focus) field.querySelector('input').focus();
}
$('#more').onclick = () => addItem();
addItem(false);

function render() {
  $('#total').textContent = rows.length + (rows.length === 1 ? ' item' : ' items');
  const search = $('#search').value.trim().toLowerCase();
  const visible = rows.filter(row => {
    const data = [ticket(row.id), row.garment, row.request].join(' ').toLowerCase();
    return (filter === 'All' || row.state === filter) && data.includes(search);
  });
  const records = $('#records');
  records.replaceChildren();
  if (!visible.length) {
    const empty = element('div','empty');
    empty.innerHTML = '<svg aria-hidden="true" viewBox="0 0 48 48"><path d="m7 19 18-12 15 3 1 14-19 13z" fill="#e9eddf"/><path d="m10 26 15-13 14-1 4 12-18 17z" fill="#f2dfbf"/><circle cx="34" cy="18" r="2"/><path d="M35 16q2-15 9-10t-8 12M18 27l9-7m-6 11 8-6"/></svg>';
    empty.append(element('h3','',rows.length ? 'No matching items' : 'Your queue is empty'),
      element('p','',rows.length ? 'Try another search or status filter.' : 'Save an intake to see its tickets here.'));
    records.append(empty);
  }
  for (const row of visible) {
    const card = element('article','row');
    const description = element('div','description');
    description.append(element('strong','',row.garment),element('small','',row.request));
    const status = element('select');
    status.id = 'status-' + row.id;
    status.setAttribute('aria-label','Status for ' + ticket(row.id) + ' ' + row.garment);
    states.forEach(s => status.add(new Option(s, s)));
    status.value = status.dataset.state = row.state;
    status.onchange = () => changeStatus(row.id,status);
    card.append(element('span','tag',ticket(row.id)),description,status);
    records.append(card);
  }
}
for (const state of ['All', ...states]) {
  const button = element('button','',state);
  button.setAttribute('aria-pressed',state === filter);
  button.onclick = () => {
    filter = state;
    for (const b of $('#filters').children) b.setAttribute('aria-pressed', b === button);
    render();
  };
  $('#filters').append(button);
}
$('#search').oninput = render;
function transaction(mode, run) {
  return new Promise((resolve,reject) => {
    const tx = db.transaction('items',mode);
    tx.oncomplete = resolve;
    tx.onabort = () => reject(tx.error || new Error('Transaction aborted'));
    run(tx.objectStore('items'));
  });
}
async function refresh() {
  let items;
  await transaction('readonly',store => {
    const read = store.getAll();
    read.onsuccess = () => { items = read.result; };
  });
  rows = items.reverse();
  render();
}
async function changeStatus(id,select) {
  const state = select.value;
  select.disabled = true;
  try {
    await transaction('readwrite',store => {
      const read = store.get(id);
      read.onsuccess = () => store.put({...read.result, state});
    });
    report('');
    message(ticket(id) + ' marked ' + state.toLowerCase() + '.');
  } catch {
    report('Status change could not be saved. Check available browser storage and try again.');
  }
  await refresh();
  (document.getElementById('status-' + id) || $('#filters [aria-pressed=true]')).focus();
}
$('#intake').onsubmit = async event => {
  event.preventDefault();
  if (!db || saving) return;
  const items = [];
  for (const field of $('#fields').children) {
    const garment = field.querySelector('.garment');
    const request = field.querySelector('.request');
    const source = request.value === 'Other repair' ? field.querySelector('.detail input') : request;
    for (const input of [garment,source]) {
      if (!input.value.trim()) {
        input.setCustomValidity('Enter a short description.');
        input.reportValidity();
        input.oninput = () => input.setCustomValidity('');
        return;
      }
    }
    items.push({garment:garment.value.trim(),request:source.value.trim(),state:'Waiting'});
  }
  const ids = [];
  saving = true;
  $('#save').disabled = true;
  try {
    await transaction('readwrite',store => {
      items.forEach(item => {
        const write = store.add(item);
        write.onsuccess = () => ids.push(write.result);
      });
    });
  } catch {
    report('Intake could not be saved. Your entries are still in the form. Check browser storage and try again.');
    return;
  } finally {
    saving = false;
    $('#save').disabled = false;
  }
  report('');
  message('Intake saved. Tag each garment: ' + items.map((item,i) => ticket(ids[i]) + ' · ' + item.garment).join(' / '));
  $('#fields').replaceChildren();
  addItem();
  $('#search').value = '';
  $('#filters button').click();
  await refresh();
};
async function start() {
  try {
    db = await new Promise((resolve,reject) => {
      const open = indexedDB.open('mending-table-repair-desk',1);
      open.onupgradeneeded = () => open.result.createObjectStore('items',{keyPath:'id',autoIncrement:true});
      open.onsuccess = () => resolve(open.result);
      open.onerror = () => reject(open.error);
    });
    await refresh();
    $('#save').disabled = false;
    window.addEventListener('focus',refresh);
  } catch {
    report('Local records could not be opened. Open this file in a regular browser window with local storage enabled, then reload.');
  }
}
start();

"use strict";

const byId = id => document.getElementById(id);
const statusNames = { waiting: "Waiting", progress: "In progress", ready: "Ready" };
const itemLetters = ["A", "B", "C"];
const formatDate = new Intl.DateTimeFormat("en", { weekday: "short", month: "short", day: "numeric", year: "numeric" });
const intakeForm = byId("intake-form");
const fields = byId("item-fields");
const search = byId("search");
const scope = byId("date-scope");
const filters = byId("filters");
const rows = byId("rows");
const dialog = byId("tags-dialog");

let database;
let tickets = [];
let day = "";
let activeFilter = "all";
let nextFieldId = 0;
let latestTicket;
let undoMove;
let saving = false;
let updating = false;
let changes;
try {
  if (typeof BroadcastChannel === "function") changes = new BroadcastChannel("mend-desk");
} catch {
  // Some browser policies restrict messaging between local files.
}

function element(tag, className, content) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (content !== undefined) node.textContent = content;
  return node;
}

function localDay(date) {
  return [date.getFullYear(), String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0")].join("-");
}

function updateDay() {
  const now = new Date();
  const currentDay = localDay(now);
  if (day === currentDay) return;
  day = currentDay;
  byId("today").dateTime = day;
  byId("today").textContent = formatDate.format(now);
  if (database) renderBoard();
}

function ticketCode(id) {
  return String(id).padStart(3, "0");
}

function itemCode(id, index) {
  return ticketCode(id) + "-" + itemLetters[index];
}

function repairSummary(item) {
  return item.repair === "Other" ? item.detail : [item.repair, item.detail].filter(Boolean).join(" · ");
}

function openDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open("mend-desk-intake", 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore("tickets", { keyPath: "id", autoIncrement: true });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
    request.onblocked = () => storageFailure("Close other Mend Desk tabs, then reload this page.");
  });
}

function transact(mode, run) {
  return new Promise((resolve, reject) => {
    const tx = database.transaction("tickets", mode);
    const store = tx.objectStore("tickets");
    let result;
    let failure;
    tx.oncomplete = () => resolve(result);
    tx.onabort = () => reject(failure || tx.error || new Error("The storage operation was interrupted."));
    run(store, value => { result = value; }, error => {
      failure = error;
      tx.abort();
    });
  });
}

async function readBoard() {
  if (!database) return;
  try {
    const records = await transact("readonly", (store, done) => {
      const request = store.getAll();
      request.onsuccess = () => done(request.result);
    });
    tickets = records.reverse();
    if (document.activeElement?.matches(".status-select") && !updating) return;
    renderBoard();
  } catch {
    storageFailure("The repair board could not be read. Reload to reconnect to local storage.");
  }
}

function storageFailure(message) {
  byId("storage").dataset.state = "error";
  byId("storage-text").textContent = "Storage unavailable";
  byId("storage-error").textContent = message;
  byId("storage-error").hidden = false;
  byId("save-ticket").disabled = true;
  if (!database) {
    byId("empty-title").textContent = "Board unavailable";
    byId("result-count").textContent = "Storage unavailable";
  }
}

function normalise(value) {
  return value.trim().toLowerCase();
}

function matchesSearch(ticket, item, index, terms) {
  const code = itemCode(ticket.id, index).toLowerCase();
  const haystack = [code, ticket.id, item.garment, item.repair, item.detail, statusNames[item.status]].join(" ").toLowerCase();
  const codeTerms = terms.match(/^#?0*(\d+)(?:\s*-?\s*([abc]))?$/);
  if (codeTerms) {
    const [, id, letter] = codeTerms;
    return Number(id) === ticket.id && (!letter || letter === itemLetters[index].toLowerCase());
  }
  return terms.split(/\s+/).every(word => haystack.includes(word));
}

function setFeedback(message, isError = false) {
  byId("board-message").textContent = message;
  byId("board-feedback").hidden = !message;
  byId("board-feedback").dataset.error = String(isError);
  const undoButton = byId("undo");
  undoButton.hidden = !undoMove;
  if (undoMove) undoButton.setAttribute("aria-label", "Undo status change for " + itemCode(undoMove.id, undoMove.index));
}

function refreshItemFields() {
  const groups = Array.from(fields.children);
  groups.forEach((group, index) => {
    group.querySelector("legend").textContent = "Item " + itemLetters[index];
    const remove = group.querySelector(".remove-item");
    remove.hidden = groups.length === 1;
    remove.setAttribute("aria-label", "Remove item " + itemLetters[index]);
  });
  const add = byId("add-item");
  add.disabled = groups.length >= itemLetters.length;
  add.textContent = add.disabled ? "3-item limit reached" : "＋ Add another item";
}

function addItem(focus = false) {
  if (fields.children.length >= itemLetters.length) return;
  const group = byId("item-template").content.firstElementChild.cloneNode(true);
  nextFieldId += 1;
  for (const input of group.querySelectorAll("[data-field]")) {
    input.id = input.dataset.field + "-" + nextFieldId;
    group.querySelector('[data-label="' + input.dataset.field + '"]').htmlFor = input.id;
  }
  const repair = group.querySelector('[data-field="repair"]');
  const detail = group.querySelector('[data-field="detail"]');
  const detailLabel = detail.previousElementSibling.querySelector(".optional");
  repair.addEventListener("change", () => {
    detail.required = repair.value === "Other";
    detailLabel.textContent = detail.required ? "(required for Other)" : "(optional)";
  });
  group.querySelector(".remove-item").addEventListener("click", () => {
    const next = group.nextElementSibling || group.previousElementSibling;
    group.remove();
    refreshItemFields();
    next?.querySelector("input").focus();
  });
  fields.append(group);
  refreshItemFields();
  if (focus) group.querySelector("input").focus();
}

function createRow(ticket, item, index, showDate) {
  const code = itemCode(ticket.id, index);
  const tr = element("tr");
  const tagCell = tr.insertCell();
  const tag = element("button", "button ticket-link", code);
  tag.type = "button";
  tag.setAttribute("aria-label", "View tags for " + code);
  tag.addEventListener("click", () => openTags(ticket));
  tagCell.append(tag);
  if (showDate) {
    const date = element("time", "item-date", ticket.day);
    date.dateTime = ticket.day;
    date.style.display = "block";
    tagCell.append(date);
  }
  const requestCell = tr.insertCell();
  requestCell.append(element("div", "garment", item.garment),
    element("div", "repair", repairSummary(item)));
  const statusCell = tr.insertCell();
  const select = element("select", "status-select " + item.status);
  select.dataset.code = code;
  select.setAttribute("aria-label", "Status of " + code + ", " + item.garment);
  for (const [value, label] of Object.entries(statusNames)) select.add(new Option(label, value));
  select.value = item.status;
  select.addEventListener("change", () => changeStatus(ticket.id, index, item.status, select.value));
  statusCell.append(select);
  return tr;
}

function renderBoard() {
  const focusedCode = document.activeElement?.dataset.code;
  const terms = normalise(search.value);
  const counts = { all: 0, waiting: 0, progress: 0, ready: 0 };
  const visible = [];
  for (const ticket of tickets) {
    if (scope.value === "today" && ticket.day !== day) continue;
    ticket.items.forEach((item, index) => {
      counts.all += 1;
      counts[item.status] += 1;
      if ((activeFilter === "all" || activeFilter === item.status) &&
          (!terms || matchesSearch(ticket, item, index, terms))) {
        visible.push(createRow(ticket, item, index, scope.value === "all"));
      }
    });
  }
  for (const button of filters.querySelectorAll("button")) {
    button.setAttribute("aria-pressed", String(activeFilter === button.dataset.filter));
    button.querySelector("span").textContent = counts[button.dataset.filter];
  }
  rows.replaceChildren(...visible);
  const hasItems = visible.length > 0;
  byId("table").hidden = !hasItems;
  byId("empty").hidden = hasItems;
  const filtered = Boolean(terms) || activeFilter !== "all";
  byId("empty-title").textContent = filtered ? "No matching items" : "The board is clear";
  byId("empty-copy").textContent = filtered ? "Try a different search or status. Use All dates to look through earlier café days." :
    scope.value === "today" ? "Save a ticket to add its items to today’s waiting list." : "Save a ticket to add its items to the waiting list.";
  byId("clear-filters").hidden = !filtered;
  byId("result-count").textContent = visible.length + " of " + counts.all + (counts.all === 1 ? " item" : " items");
  if (focusedCode) {
    const matchingControl = Array.from(rows.querySelectorAll("select")).find(select => select.dataset.code === focusedCode);
    (matchingControl || (undoMove ? byId("undo") : search)).focus();
  }
}

async function saveTicket(event) {
  event.preventDefault();
  if (!database || saving) return;
  byId("form-error").hidden = true;
  const items = [];
  for (const group of fields.children) {
    const garment = group.querySelector('[data-field="garment"]');
    const repair = group.querySelector('[data-field="repair"]');
    const detail = group.querySelector('[data-field="detail"]');
    const invalid = !garment.value.trim() ? garment : repair.value === "Other" && !detail.value.trim() ? detail : null;
    if (invalid) {
      byId("form-error").textContent = invalid === garment ? "Enter a garment description for each item." : "Describe the repair when choosing Other.";
      byId("form-error").hidden = false;
      invalid.focus();
      return;
    }
    items.push({ garment: garment.value.trim(), repair: repair.value, detail: detail.value.trim(), status: "waiting", revision: 0 });
  }
  updateDay();
  const record = { day, items };
  saving = true;
  const saveButton = byId("save-ticket");
  saveButton.disabled = true;
  try {
    const id = await transact("readwrite", (store, done) => {
      const request = store.add(record);
      request.onsuccess = () => done(request.result);
    });
    latestTicket = { ...record, id };
  } catch {
    byId("form-error").textContent = "The ticket was not saved. Your entries are still here. Try saving again.";
    byId("form-error").hidden = false;
    return;
  } finally {
    saving = false;
    saveButton.disabled = !database;
  }
  tickets = [latestTicket, ...tickets.filter(ticket => ticket.id !== latestTicket.id)];
  fields.replaceChildren();
  addItem(true);
  const codes = items.map((_, index) => itemCode(latestTicket.id, index));
  byId("receipt-text").textContent = "Saved · " + codes.join(", ");
  byId("receipt").hidden = false;
  if (!undoMove) setFeedback("");
  renderBoard();
  changes?.postMessage("changed");
  void readBoard();
}

async function changeStatus(id, index, from, to, expectedRevision = null) {
  if (!database || updating || from === to) {
    renderBoard();
    return;
  }
  const code = itemCode(id, index);
  const isUndo = expectedRevision !== null;
  updating = true;
  try {
    const changed = await transact("readwrite", (store, done, abort) => {
      const request = store.get(id);
      request.onsuccess = () => {
        const ticket = request.result;
        const item = ticket?.items[index];
        if (!item || item.status !== from || (isUndo && item.revision !== expectedRevision)) {
          abort(new Error("This item changed in another tab."));
          return;
        }
        item.status = to;
        item.revision = (item.revision || 0) + 1;
        store.put(ticket);
        done(ticket);
      };
    });
    tickets = tickets.map(ticket => ticket.id === id ? changed : ticket);
    undoMove = isUndo ? null : { id, index, from: to, to: from, revision: changed.items[index].revision };
    setFeedback(code + (isUndo ? " restored to " : " moved to ") + statusNames[to] + ".");
    changes?.postMessage("changed");
  } catch (error) {
    if (isUndo) undoMove = null;
    setFeedback(code + " could not be updated. " + (error.message === "This item changed in another tab." ?
      error.message : "Try changing its status again."), true);
  } finally {
    const undoHadFocus = document.activeElement === byId("undo");
    await readBoard();
    if (undoHadFocus && !undoMove) search.focus();
    updating = false;
  }
}

function makeTag(code, title, lines) {
  const tag = element("section", "print-tag");
  tag.append(element("p", "eyebrow", title), element("p", "print-code", code));
  for (const line of lines) tag.append(element("p", "", line));
  return tag;
}

function openTags(ticket) {
  byId("tags-heading").textContent = "Ticket " + ticketCode(ticket.id);
  const pairs = ticket.items.map((item, index) => {
    const code = itemCode(ticket.id, index);
    const pair = element("div", "tag-pair");
    pair.append(makeTag(code, "Garment tag", [item.garment, repairSummary(item)]),
      makeTag(code, "Pickup slip", [item.garment, "Bring this slip to pickup."]));
    return pair;
  });
  byId("tag-pairs").replaceChildren(...pairs);
  dialog.showModal();
}

updateDay();
addItem();
byId("add-item").addEventListener("click", () => addItem(true));
intakeForm.addEventListener("submit", saveTicket);
byId("receipt-tags").addEventListener("click", () => openTags(latestTicket));
byId("print-tags").addEventListener("click", () => window.print());
window.addEventListener("beforeprint", () => document.body.classList.toggle("printing", dialog.open));
window.addEventListener("afterprint", () => document.body.classList.remove("printing"));
byId("undo").addEventListener("click", () => {
  if (undoMove) changeStatus(undoMove.id, undoMove.index, undoMove.from, undoMove.to, undoMove.revision);
});
search.addEventListener("input", renderBoard);
scope.addEventListener("change", renderBoard);
filters.addEventListener("click", event => {
  const button = event.target.closest("button[data-filter]");
  if (!button) return;
  activeFilter = button.dataset.filter;
  renderBoard();
});
byId("clear-filters").addEventListener("click", () => {
  search.value = "";
  activeFilter = "all";
  renderBoard();
  search.focus();
});
changes?.addEventListener("message", () => { void readBoard(); });
window.addEventListener("focus", () => {
  updateDay();
  void readBoard();
});
window.setInterval(updateDay, 60_000);

async function start() {
  try {
    database = await openDatabase();
    database.onversionchange = () => {
      database.close();
      database = null;
      storageFailure("Storage changed in another tab. Reload to reconnect.");
    };
    byId("storage-error").hidden = true;
    byId("storage").dataset.state = "ready";
    byId("storage-text").textContent = "Stored on this device";
    byId("save-ticket").disabled = false;
    await readBoard();
  } catch {
    storageFailure("Local storage could not be opened. Use a regular browser window and reopen this file.");
  }
}

void start();

:root {
  color-scheme: light;
  --canvas: #f2f0e8;
  --paper: #fffcf5;
  --white: #fffefa;
  --forest: #173d33;
  --ink: #18332c;
  --muted: #505e55;
  --line: #d5d7ca;
  --control: #a8afa0;
  --gold: #ead198;
  --waiting: #79541a;
  --waiting-bg: #f7edcf;
  --progress: #34566a;
  --progress-bg: #e9eff3;
  --ready: #2b5b48;
  --ready-bg: #e6efe5;
  --focus: #2f6f86;
  font: 100%/1.5 system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--canvas);
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; }
button, input, select { font: inherit; }
button, select { cursor: pointer; }
button:disabled { cursor: default; opacity: .55; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.skip { position: fixed; z-index: 2; top: .5rem; left: 1rem; transform: translateY(-160%); padding: .7rem; background: var(--white); color: var(--ink); }
.skip:focus { transform: translateY(0); }
h1, h2, h3, p { margin: 0; }
.shell { width: min(100% - 4rem, 76rem); margin-inline: auto; }
.topbar { color: var(--paper); background: var(--forest); border-bottom: 3px solid var(--gold); }
.topbar-inner { min-height: 4.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.brand { display: flex; align-items: center; gap: .7rem; font: bold 1.35rem/1 Georgia, serif; }
.brand-mark { display: grid; place-items: center; width: 2rem; height: 2rem; border: 1px dashed #bea870; border-radius: .35rem; color: var(--gold); font: 1rem/1 system-ui, sans-serif; transform: rotate(-7deg); }
.storage { display: flex; gap: .5rem; align-items: center; color: #f3ecdc; font-size: .84rem; }
.storage > span:first-child { display: block; border-radius: 50%; width: .5rem; height: .5rem; background: var(--gold); }
.storage[data-state="ready"] > span:first-child { background: #baddbd; }
.storage[data-state="error"] > span:first-child { background: #ffad94; }
.intro { display: flex; justify-content: space-between; align-items: end; gap: 1.5rem; padding: 2.6rem 0 1.7rem; margin-bottom: 1.55rem; border-bottom: 1px dashed #a3ab96; }
.eyebrow { color: var(--muted); text-transform: uppercase; letter-spacing: .13em; font-size: .72rem; font-weight: 750; }
h1 { font: 500 clamp(2.55rem, 5vw, 4rem)/1.05 Georgia, serif; letter-spacing: -.047em; margin: .2rem 0 .55rem; }
.intro p:not(.eyebrow), .panel-heading p, .empty p, .dialog-hint { color: var(--muted); }
.date-stamp { min-width: 10.8rem; padding: .65rem 1rem; border: 1px solid #c6c8b6; outline: 1px dashed #bfc2af; outline-offset: -5px; border-radius: .4rem; background: #eaece0; }
.date-stamp time { display: block; font-weight: 680; }
.workspace { display: grid; grid-template-columns: minmax(18rem, 22rem) minmax(0, 1fr); gap: 1.5rem; align-items: start; }
.panel { min-width: 0; background: var(--paper); border: 1px solid var(--line); border-radius: .9rem; box-shadow: 0 2px 2px #18332c0a; }
.panel-heading { display: flex; align-items: center; gap: .8rem; padding: 1.2rem 1.25rem; border-bottom: 1px solid var(--line); }
.heading-mark { width: 2.5rem; height: 2.5rem; flex: 0 0 auto; display: grid; place-items: center; border-radius: .55rem; background: var(--waiting-bg); color: var(--waiting); font-size: 1.65rem; }
.board-mark { background: var(--ready-bg); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: .23rem; }
.board-mark span { width: .95rem; height: 2px; background: var(--forest); border-radius: 1rem; }
h2 { font: 600 1.65rem/1.1 Georgia, serif; letter-spacing: -.025em; }
.panel-heading p { margin-top: .22rem; font-size: .875rem; }
#intake-form { padding: 1rem 1.25rem 1.25rem; }
.item { position: relative; min-width: 0; margin: 0 0 .85rem; padding: .55rem 0 .2rem; border: 0; }
.item + .item { padding-top: .65rem; border-top: 1px dashed #a3ab96; }
.item legend { padding: 0 .45rem 0 0; font-weight: 750; font-size: .8rem; letter-spacing: .07em; text-transform: uppercase; }
.field { margin-top: .65rem; }
label { display: block; margin-bottom: .25rem; font-weight: 670; font-size: .85rem; }
.optional { color: var(--muted); font-weight: normal; }
input, select { width: 100%; min-width: 0; min-height: 2.75rem; padding: .52rem .66rem; border: 1px solid var(--control); border-radius: .42rem; background: var(--white); color: var(--ink); }
input::placeholder { color: #5e675c; opacity: 1; }
select { padding-right: .4rem; }
.button, .remove-item { display: inline-flex; justify-content: center; align-items: center; gap: .55rem; min-height: 2.75rem; border: 1px solid var(--control); border-radius: .45rem; background: var(--white); color: var(--forest); padding: .5rem .8rem; font-weight: 690; line-height: 1.2; }
.button:hover:not(:disabled), .remove-item:hover { background: var(--ready-bg); }
.add-item { width: 100%; border-style: dashed; }
.remove-item { position: absolute; top: -.8rem; right: 0; min-height: 2.75rem; font-size: .82rem; background: var(--paper); z-index: 1; }
.item:has(.remove-item:not([hidden])) { padding-top: 1.5rem; }
.intake-footer { margin-top: 1rem; }
.primary { background: var(--forest); border-color: var(--forest); color: var(--white); }
.primary:hover:not(:disabled) { background: #285547; }
#save-ticket { width: 100%; justify-content: space-between; padding-inline: .9rem; }
.error { color: #872e23; margin-top: .7rem; font-size: .9rem; }
.storage-error { border: 1px solid #d5a69b; background: #fff2eb; margin: 0 0 1rem; padding: .8rem 1rem; border-radius: .45rem; }
.receipt { display: flex; flex-wrap: wrap; gap: .5rem; justify-content: space-between; align-items: center; margin: 0 1.25rem 1.25rem; border-radius: .5rem; background: var(--ready-bg); padding: .6rem .7rem; font-size: .88rem; }
.small-button { font-size: .85rem; }
.board-controls { padding: 1rem 1.25rem; }
.lookup { display: grid; grid-template-columns: minmax(0, 1fr) minmax(7rem, .29fr); gap: .75rem; }
.search-box { position: relative; }
.search-box input { padding-left: 2.3rem; }
.magnifier { position: absolute; left: .88rem; top: .92rem; width: .68rem; height: .68rem; border: 1.6px solid var(--muted); border-radius: 50%; pointer-events: none; }
.magnifier::after { content: ""; background: var(--muted); width: .32rem; height: 1.6px; position: absolute; top: .53rem; left: .46rem; transform: rotate(45deg); transform-origin: left center; }
.filters { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .5rem; margin-top: .9rem; }
.filters button { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: .33rem; min-height: 2.75rem; background: var(--white); color: var(--ink); border: 1px solid var(--control); border-radius: .45rem; padding: .35rem; font-size: .82rem; font-weight: 660; }
.filters button:hover { background: #edf0e5; }
.filters button[aria-pressed="true"] { background: var(--ready-bg); border-color: var(--forest); box-shadow: inset 0 0 0 1px var(--forest); }
.filters button span { padding: .04rem .3rem; min-width: 1.25rem; border-radius: .3rem; background: #eceee5; color: var(--ink); font-variant-numeric: tabular-nums; }
.dot { display: inline-block; width: .53rem; height: .53rem; border-radius: 50%; }
.dot.waiting { background: var(--waiting); }
.dot.progress { background: var(--progress); }
.dot.ready { background: var(--ready); }
.board-feedback { display: flex; align-items: center; justify-content: space-between; gap: .6rem; padding: .45rem .7rem; margin: 0 1.25rem .65rem; border: 1px solid var(--line); border-radius: .45rem; background: #f0f1e7; font-size: .875rem; }
.board-feedback[data-error="true"] { background: #fff2eb; color: #872e23; }
.table { border-top: 1px solid var(--line); }
table { width: 100%; border-collapse: collapse; text-align: left; }
th, td { padding: .65rem .6rem; }
th:first-child, td:first-child { padding-left: 1.25rem; }
th:last-child, td:last-child { padding-right: 1.25rem; }
thead { background: #edf0e6; color: var(--muted); font-size: .72rem; letter-spacing: .09em; text-transform: uppercase; }
tbody tr { border-top: 1px solid var(--line); }
tbody tr:hover { background: #f6f5ec; }
td { overflow-wrap: anywhere; }
td:last-child { width: 10.5rem; }
.ticket-link { white-space: nowrap; font-family: ui-monospace, monospace; color: var(--forest); background: #f2ebd8; border-color: #c3b58f; }
.garment { font-weight: 730; }
.repair, .item-date { color: var(--muted); font-size: .85rem; }
.status-select { font-size: .89rem; font-weight: 650; }
.status-select.waiting { color: var(--waiting); background: var(--waiting-bg); }
.status-select.progress { color: var(--progress); background: var(--progress-bg); }
.status-select.ready { color: var(--ready); background: var(--ready-bg); }
.empty { min-height: 16rem; text-align: center; display: grid; justify-items: center; align-content: center; gap: .4rem; padding: 1.4rem; margin: 0 1.25rem 1rem; border: 1px dashed #aeb5a3; border-radius: .7rem; background: #f6f5ed; }
.empty h3 { font: 600 1.4rem/1.2 Georgia, serif; }
.empty p { max-width: 32ch; font-size: .9rem; }
.empty button { margin-top: .35rem; }
.tag-art { position: relative; width: 5.1rem; height: 4.2rem; margin-bottom: .3rem; }
.tag-art::before, .tag-art::after { content: ""; position: absolute; z-index: 0; top: 19%; left: 14%; width: 72%; height: 61%; border: 1px solid #8f9e87; border-radius: .18rem .45rem .45rem .18rem; background: var(--ready-bg); transform: rotate(17deg); }
.tag-art::after { border-color: #aa8e53; background: var(--waiting-bg); transform: translate(-.18rem, -.15rem) rotate(-16deg); }
.tag-art span { position: absolute; z-index: 1; top: 46%; left: 56%; width: .42rem; height: .42rem; border: 1px solid #9d824a; border-radius: 50%; background: var(--paper); transform: translate(.44rem, -.4rem); }
.tag-art span + span { top: 46%; left: 22%; width: 1.6rem; height: .49rem; border: 0; border-block: 1px dashed #9d824a; border-radius: 0; background: none; transform: rotate(-16deg); }
.board-footer { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .25rem 1rem; padding: .72rem 1.25rem; border-top: 1px solid var(--line); color: var(--muted); font-size: .82rem; }
.desk-footer { margin: 1.25rem 0 0; padding: .8rem 0 1.25rem; display: flex; justify-content: space-between; flex-wrap: wrap; gap: .25rem 1rem; color: var(--muted); border-top: 1px dashed #a3ab96; font-size: .84rem; }
dialog { width: min(39rem, calc(100% - 2rem)); max-height: calc(100% - 2rem); border: 1px solid var(--line); border-radius: .85rem; padding: 1.25rem; background: var(--paper); color: var(--ink); }
dialog::backdrop { background: #10261f9e; }
.dialog-header { display: flex; align-items: start; justify-content: space-between; gap: .7rem; }
.dialog-header h2 { margin-top: .22rem; }
.dialog-hint { margin: .75rem 0; font-size: .92rem; }
.tag-pair { display: grid; grid-template-columns: 1.45fr 1fr; border: 1px solid var(--control); margin-bottom: .65rem; border-radius: .45rem; background: var(--white); }
.print-tag { padding: .75rem; overflow-wrap: anywhere; }
.print-tag + .print-tag { border-left: 1px dashed var(--control); }
.print-code { font: 700 1.5rem/1.25 ui-monospace, monospace; margin: .2rem 0; }
.dialog-actions { display: flex; justify-content: end; }

@media (max-width: 68rem) {
  .shell { width: calc(100% - 2.5rem); }
  .workspace { grid-template-columns: minmax(16rem, 19rem) minmax(0, 1fr); gap: 1rem; }
}
@media (max-width: 52rem) {
  .workspace { grid-template-columns: 1fr; }
  .intro { padding-top: 1.6rem; }
}
@media (max-width: 30rem) {
  .shell { width: calc(100% - 1.5rem); }
  .storage { font-size: .76rem; }
  .intro { flex-wrap: wrap; gap: .8rem; }
  .date-stamp { display: flex; gap: .65rem; align-items: center; font-size: .87rem; }
  .panel-heading, #intake-form, .board-controls, .board-footer { padding-inline: .8rem; }
  .filters { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .empty, .board-feedback, .receipt { margin-inline: .8rem; }
  th, td { padding-inline: .28rem; }
  th:first-child, td:first-child { padding-left: .5rem; }
  th:last-child, td:last-child { padding-right: .5rem; }
  td:last-child { width: auto; }
  .ticket-link, .status-select { font-size: .77rem; padding-inline: .3rem; }
}
@media print {
  @page { margin: 12mm; }
  :root, body { background: #fff; color: #000; }
  body.printing > :not(#tags-dialog), .dialog-header, .dialog-hint, .dialog-actions { display: none !important; }
  dialog[open] { position: static; display: block; border: 0; padding: 0; margin: 0; width: 100%; max-width: none; max-height: none; overflow: visible; background: #fff; color: #000; }
  dialog::backdrop { background: transparent; }
  .tag-pair { break-inside: avoid; border-color: #000; }
  .print-tag + .print-tag { border-color: #000; }
  .print-tag .eyebrow { color: #000; }
}
